// Builds n mock farmers. Pure: it only reads the index built by buildOriginItems_().
// Each answer is [questionId, optionKey]. Nothing is written here.
function generateMockFarmers_(index, n, seed) {
  const rnd = rng_(seed);
  const pick = a => a[Math.floor(rnd() * a.length)];
  const chance = p => rnd() < p;
  const int = (lo, hi) => lo + Math.floor(rnd() * (hi - lo + 1));
  const weighted = pairs => {
    const total = pairs.reduce((s, p) => s + p[1], 0);
    let r = rnd() * total;
    for (let i = 0; i < pairs.length; i++) { r -= pairs[i][1]; if (r < 0) return pairs[i][0]; }
    return pairs[pairs.length - 1][0];
  };
  const pad = (v, w) => String(v).padStart(w, '0');

  const plan = [];
  [['Anuradhapura', 0.35], ['Polonnaruwa', 0.20], ['Ampara', 0.25], ['Hambantota', 0.20]].forEach(p => {
    for (let i = 0; i < Math.round(n * p[1]); i++) plan.push(p[0]);
  });
  while (plan.length < n) plan.push('Anuradhapura');
  plan.length = n;
  for (let i = plan.length - 1; i > 0; i--) { const j = Math.floor(rnd() * (i + 1)); const t = plan[i]; plan[i] = plan[j]; plan[j] = t; }

  const dsByDistrict = {};
  Object.keys(index.ds).forEach(k => { (dsByDistrict[index.ds[k].district] = dsByDistrict[index.ds[k].district] || []).push(k); });

  const usedNic = {};
  const usedPhone = {};
  const farmers = [];
  const startTime = Date.UTC(2025, 10, 1);
  const spanTime = Date.UTC(2026, 9, 20) - startTime;

  for (let i = 0; i < n; i++) {
    const district = plan[i];
    const dsName = pick(dsByDistrict[district]);
    const d = index.ds[dsName];

    // ethnicity decides the name style and language
    const eastern = EAST_ETHNICITY[dsName];
    let eth = 'S';
    if (eastern === 'M') eth = 'M';
    else if (eastern === 'T') eth = 'T';
    else if (eastern === 'MT') eth = chance(0.5) ? 'M' : 'T';
    else eth = weighted([['S', 94], ['M', 4], ['T', 2]]);
    const female = chance(0.17);
    const pool = NAMES[eth];
    const given = pick(female ? pool.female : pool.male);
    let name;
    if (eth === 'S') name = chance(0.4) ? given + ' ' + pick(pool.middle) + ' ' + pick(pool.surname) : given + ' ' + pick(pool.surname);
    else name = given + ' ' + pick(pool.surname);
    const language = eth === 'S' ? 'Sinhala' : (eth === 'M' && !eastern && chance(0.3) ? 'Sinhala' : 'Tamil');

    // NIC and date of birth agree with each other
    const year = int(1950, 2002);
    const doy = int(1, 365);
    const dob = new Date(Date.UTC(year, 0, doy)).toISOString().slice(0, 10);
    let nic = '';
    if (!chance(0.1)) {
      for (let tries = 0; tries < 20; tries++) {
        const day = pad(female ? doy + 500 : doy, 3);
        const useNew = year >= 2000 || chance(0.25);
        const candidate = useNew ? String(year) + day + pad(int(0, 9999), 4) + int(0, 9) : String(year).slice(2) + day + pad(int(0, 999), 3) + int(0, 9) + 'V';
        if (!usedNic[candidate]) { usedNic[candidate] = true; nic = candidate; break; }
      }
    }

    let phone = '';
    while (!phone || usedPhone[phone]) phone = '+94' + weighted([['70', 4], ['71', 8], ['72', 4], ['74', 3], ['75', 5], ['76', 9], ['77', 12], ['78', 7]]) + pad(int(0, 9999999), 7);
    usedPhone[phone] = true;
    let alt = '';
    if (chance(0.15)) {
      while (!alt || usedPhone[alt]) alt = '+94' + weighted([['70', 4], ['71', 8], ['72', 4], ['74', 3], ['75', 5], ['76', 9], ['77', 12], ['78', 7]]) + pad(int(0, 9999999), 7);
      usedPhone[alt] = true;
    }

    // a village that belongs to the farmer's own division: a Yaya village there, or the division town itself
    const own = (YAYA_SEED[district] || []).filter(y => y[1] === dsName).map(y => y[0]);
    const village = own.length && chance(0.6) ? pick(own) : dsName.replace(/ \((Muslim|Tamil)\)$/, '');
    const consent = weighted([['Yes', 40], ['No', 10], ['Unknown', 50]]);
    const doNotContact = consent === 'No' ? chance(0.3) : chance(0.02);

    // fields
    const fields = [];
    const fieldCount = weighted([[1, 55], [2, 32], [3, 13]]);
    for (let f = 0; f < fieldCount; f++) {
      const crop = f === 0 && chance(0.6) ? 'Paddy' : weighted([['Paddy', 70], ['Maize', 9], ['Soybean', 3], ['Chilli', 6], ['Big onion', 5], ['Vegetables', 6], ['Other', 1]]);
      const raw = crop === 'Paddy' ? Math.exp(0.7 + 0.6 * (rnd() + rnd() + rnd() - 1.5) * 1.6) : 0.25 + rnd() * 3.5;
      const acres = Math.min(15, Math.max(0.25, Math.round(raw * 4) / 4));
      const centre = DISTRICT_CENTRE[district];
      const gps = chance(0.6);
      fields.push({
        crop: crop, acres: acres,
        season: crop === 'Paddy' ? weighted([['Both', 50], ['Maha', 35], ['Yala', 15]]) : weighted([['Maha', 45], ['Yala', 45], ['Both', 10]]),
        latitude: gps ? Math.round((centre[0] + (rnd() - 0.5) * 0.3) * 1e6) / 1e6 : '',
        longitude: gps ? Math.round((centre[1] + (rnd() - 0.5) * 0.3) * 1e6) / 1e6 : '',
        notes: ''
      });
    }

    // origin answers
    const answers = [];
    const route = rnd();
    const irrigation = route < 0.55 || route >= 0.80;
    const agriculture = route >= 0.55;
    if (irrigation) {
      answers.push(['Q001', d.scheme], ['Q002', d.rpm], ['Q003', d.committee]);
      if (chance(0.65)) {
        if (chance(0.3)) d.kanna.forEach(k => answers.push(['Q008', k]));
        else answers.push(['Q008', pick(d.kanna)]);
      }
    }
    if (agriculture) {
      if (d.aiInter && chance(0.25)) {
        answers.push(['Q004', d.doaInter], ['Q005', d.interDir], ['Q006', d.aiInter]);
      } else {
        answers.push(['Q004', d.doaProv], ['Q005', d.provDir], ['Q006', d.ai]);
        if (d.yayas.length && chance(0.5)) answers.push(['Q007', pick(d.yayas)]);
        if (chance(0.5)) answers.push(['Q008', d.aiKanna]);
      }
    }

    farmers.push({
      core: {
        full_name: name, nic: nic, date_of_birth: nic || chance(0.4) ? dob : '', gender: female ? 'Female' : 'Male', language: language,
        farmer_type: weighted([['Individual farmer', 92], ['Sole proprietorship', 3], ['Partnership', 2], ['Company', 1], ['Other', 2]]),
        phone_primary: phone, phone_alt: alt,
        address: int(1, 250) + ', ' + pick(['Temple Road', 'Tank Road', 'School Lane', 'Main Street', 'Station Road', 'Canal Road']) + ', ' + village,
        district: district, ds_division: dsName, gn_division: village + pick(['', ' East', ' West', ' North', ' South']),
        village: village, marketing_consent: consent, do_not_contact: doNotContact ? 'Yes' : 'No', status: 'Active', notes: MOCK_NOTE
      },
      fields: fields,
      answers: answers,
      created: new Date(startTime + Math.floor(rnd() * spanTime))
    });
  }
  return farmers;
}

// Registers n mock farmers (default 1000) with fields and origin answers. They are written in batches, and the run stops
// before Apps Script's 6 minute limit. If it stops early, run it again with the same n: it carries on where it left off.
// budgetMs and batch are only for testing.
function seedMockFarmers(n, budgetMs, batch) {
  requireRole_(['Admin']);
  const started = Date.now();
  n = n || 1000;
  budgetMs = budgetMs === undefined ? 240000 : budgetMs;
  batch = batch || 2000;
  const existing = countMockFarmers_();
  if (existing > 0 && Number(getConfig_('mock_farmers_target')) !== n) {
    throw new Error('Mock farmers from a different run exist. Run removeMockFarmers() first.');
  }
  if (existing >= n) return { farmers: 0, fields: 0, answers: 0, done: true, total: existing };
  const optId = {};
  readAll_('FormOptions').forEach(o => { if (o.source === SEED_SOURCE) optId[o.question_id + '|' + o.label] = o.option_id; });
  if (!Object.keys(optId).length) throw new Error('Run seedOriginOptions() first.');
  const owner = currentEmail_();
  // The same n always gives the same people in the same order, so a later run can skip the ones already written.
  const gen = generateMockFarmers_(buildOriginItems_().index, n, 20261021).slice(existing);
  setConfig_('mock_farmers_target', n, 'Size of the mock farmer run in progress');

  const totals = { farmers: 0, fields: 0, answers: 0 };
  for (let from = 0; from < gen.length; from += batch) {
    const part = gen.slice(from, from + batch);
    const fieldCount = part.reduce((s, f) => s + f.fields.length, 0);
    const answerCount = part.reduce((s, f) => s + f.answers.length, 0);
    const farmerIds = nextIds_('F', 6, part.length);
    const fieldIds = nextIds_('FLD', 6, fieldCount);
    const answerIds = nextIds_('A', 6, answerCount);
    const farmerRows = [];
    const fieldRows = [];
    const answerRows = [];
    let fi = 0;
    let ai = 0;
    part.forEach((g, i) => {
      const id = farmerIds[i];
      const stamp = { created_at: g.created, created_by: owner, updated_at: g.created, updated_by: owner };
      farmerRows.push(Object.assign({ farmer_id: id }, g.core, stamp));
      g.fields.forEach(f => fieldRows.push(Object.assign({ field_id: fieldIds[fi++], farmer_id: id, active: 'Yes' }, f, stamp)));
      g.answers.forEach(a => {
        const key = a[1];   // already 'Q001|label'
        if (!optId[key]) throw new Error('Missing seeded option for ' + key);
        answerRows.push(Object.assign({ answer_id: answerIds[ai++], farmer_id: id, question_id: a[0], option_id: optId[key], value: '', active: 'Yes' }, stamp));
      });
    });
    // answers first, farmers last: a farmer only counts as written once everything of theirs is in
    appendObjects_('Fields', fieldRows);
    appendObjects_('FarmerAnswers', answerRows);
    appendObjects_('Farmers', farmerRows);
    totals.farmers += farmerRows.length; totals.fields += fieldRows.length; totals.answers += answerRows.length;
    Logger.log('Written so far: ' + (existing + totals.farmers) + ' of ' + n + ' farmers (' + Math.round((Date.now() - started) / 1000) + ' s)');
    if (from + batch < gen.length && Date.now() - started >= budgetMs) break;
  }
  const total = existing + totals.farmers;
  audit_('create', 'Farmers', '', 'seeded ' + totals.farmers + ' mock farmers, ' + totals.fields + ' fields, ' + totals.answers + ' answers (' + total + ' of ' + n + ')');
  if (total >= n) indexRebuild_();
  Logger.log(total >= n ? 'Done: ' + total + ' mock farmers.' : 'Stopped early at ' + total + ' of ' + n + '. Run seedMockFarmers(' + n + ') again to continue.');
  return { farmers: totals.farmers, fields: totals.fields, answers: totals.answers, done: total >= n, total: total };
}

// The editor's Run button cannot pass arguments, so this is the 30,000 farmer run. Run it again if it stops early.
function seedMockFarmers30000() { return seedMockFarmers(30000); }


// ---- ServiceFlow.gs
// The four steps of a service: Request -> Scheduled -> Completed -> Paid (see SERVICE_FLOW.md). One row of the Services tab is one service on one land.
// A request that names several lands makes several rows, tied together by request_group. status is Requested / Scheduled / Completed / Cancelled;
// the payment has its own payment_status (Unpaid / Partly paid / Paid / Free). Nobody completes a job or marks it paid from the map: those are done
// by their own functions here, each behind its own power (Powers.gs).
//
// Dates are ISO text (yyyy-mm-dd), times HH:MM, like the rest of the Services tab.

const REQUEST_SOURCES_ = ['Field officer', 'Hotline', 'Farmer', 'AI officer', 'Lead farmer', 'Other'];
const FLOW_ANY_POWER_ = ['service.request', 'service.schedule', 'service.assign', 'service.view', 'service.complete', 'service.payment', 'report.view'];
const FLOW_LIST_LIMIT_ = 300;        // rows sent with a list or the map
const FLOW_MAP_POINTS_ = 4000;       // pins sent with the map
const FLOW_MAX_ITEMS_ = 12;          // lands in one request
const FLOW_STARTER_TYPES_ = ['Glyphosate spraying', 'Seed broadcasting', 'Pre-emergent spraying', 'Post-emergent spraying', 'Urea spreading', 'Fungicide spraying', 'Liquid fertilizer spraying'];
// What a list needs from every service (the long texts are only read for one service).
const FLOW_COLS_ = ['service_id', 'farmer_id', 'land_id', 'request_group', 'status', 'requested_date', 'requested_by', 'request_source', 'window_from', 'window_to', 'exact_day', 'acres_requested',
  'scheduled_date', 'service_date', 'pilot_name', 'pilot_email', 'base_station', 'service_type', 'crop', 'acres_covered', 'amount_charged', 'payment_status', 'advance_paid', 'advance_amount',
  'final_amount', 'completed_on', 'paid_on', 'start_time', 'end_time', 'drone', 'scheduled_time', 'stop_order', 'assigned_on'];
const SERVICE_MONEY_COLS_ = ['amount_charged', 'payment_status', 'advance_paid', 'advance_amount', 'advance_date', 'final_amount', 'final_date', 'payment_method', 'payment_ref', 'payment_notes', 'paid_on', 'paid_by'];

function requireFlowUser_() {
  const user = currentUser_();
  if (!user) throw new Error('Not signed in.');
  if (!FLOW_ANY_POWER_.some(p => hasPower_(user, p))) throw new Error('Not authorised for role ' + user.role + '.');
  return user;
}

// ---------- small helpers ----------

function flowDate_(raw, label, o) {
  o = o || {};
  const s = String(raw === undefined || raw === null ? '' : raw).trim().slice(0, 10);
  if (!s) { if (o.required) throw new Error(label + ' is required.'); return ''; }
  if (!isIsoDate_(s)) throw new Error(label + ' is not a valid date.');
  const today = localToday_();
  if (o.notFuture && s > today) throw new Error(label + ' cannot be in the future.');
  if (o.notPast && s < today) throw new Error(label + ' cannot be before today.');
  return s;
}

function dayNumber_(iso) { const d = isoDay_(iso); return d ? Math.round(Date.UTC(Number(d.slice(0, 4)), Number(d.slice(5, 7)) - 1, Number(d.slice(8, 10))) / 86400000) : null; }
function daysBetween_(a, b) { const x = dayNumber_(a), y = dayNumber_(b); return x === null || y === null ? null : y - x; }

function windowText_(r) {
  const from = isoDay_(r.window_from), to = isoDay_(r.window_to);
  if (!to) return '';
  if (String(r.exact_day) === 'Yes') return 'On ' + to;
  return from && from !== to ? from + ' to ' + to : 'Before ' + to;
}

function moneyAllowed_(user, r) { return hasPower_(user, 'service.payment') && powerCovers_(user, 'service.payment', r); }

// The lands and the farmers, looked up once per request.
function flowContext_() {
  const lands = {};
  readColumns_('Fields', ['field_id', 'farmer_id', 'acres', 'crop', 'active', 'land_name', 'district', 'ds_division', 'village', 'tank', 'latitude', 'longitude']).forEach(l => { lands[l.field_id] = l; });
  return { lands: lands, farmers: indexLoad_().byId };
}

function placeOfLand_(land, farmer) {
  const v = farmer ? farmer.v : [];
  return {
    village: (land && land.village) || v[11] || '', ds_division: (land && land.ds_division) || v[10] || '', district: (land && land.district) || v[9] || ''
  };
}

function landLabel_(land, id) {
  if (!land) return id ? id : 'Land not recorded';
  return String(land.land_name || land.tank || land.village || land.field_id) + ' · ' + (Number(land.acres) || 0) + ' ac';
}

// One service as a list line (and a map pin): the farmer's name, the land, the place, where it is on the road, the money only for people who may see it.
function flowCard_(r, ctx, user, today) {
  const land = r.land_id ? ctx.lands[r.land_id] : null;
  const farmer = ctx.farmers[r.farmer_id];
  const place = placeOfLand_(land, farmer);
  let lat = '', lng = '';
  if (land && land.latitude !== '' && land.longitude !== '' && land.latitude !== undefined) { lat = Number(land.latitude); lng = Number(land.longitude); }
  else if (farmer && farmer.v[16] !== '' && farmer.v[17] !== '') { lat = Number(farmer.v[16]); lng = Number(farmer.v[17]); }
  const status = String(r.status);
  const to = isoDay_(r.window_to);
  const card = {
    service_id: r.service_id, farmer_id: r.farmer_id, farmer_name: farmer ? farmer.v[1] : r.farmer_id, farmer_phone: farmer ? farmer.v[7] : '',
    land_id: r.land_id || '', land_label: landLabel_(land, r.land_id), village: place.village, ds_division: place.ds_division, district: place.district,
    latitude: lat === '' || !isFinite(lat) ? '' : lat, longitude: lng === '' || !isFinite(lng) ? '' : lng, located: lat !== '' && isFinite(lat),
    status: status, service_type: r.service_type, crop: r.crop,
    acres: status === 'Completed' ? (Number(r.acres_covered) || 0) : (Number(r.acres_requested) || (land ? Number(land.acres) || 0 : 0)),
    requested_date: isoDay_(r.requested_date), requested_by: r.requested_by, request_source: r.request_source, request_group: r.request_group,
    window_from: isoDay_(r.window_from), window_to: to, exact_day: String(r.exact_day) === 'Yes', window_text: windowText_(r),
    scheduled_date: isoDay_(r.scheduled_date) || (status === 'Scheduled' || status === 'Completed' ? isoDay_(r.service_date) : ''),
    service_date: status === 'Completed' ? isoDay_(r.service_date) : '', completed_on: isoDay_(r.completed_on),
    pilot_name: r.pilot_name, pilot_email: r.pilot_email, base_station: r.base_station, drone: String(r.drone || ''), scheduled_time: timeText_(r.scheduled_time), stop_order: r.stop_order === '' ? '' : Number(r.stop_order) || '',
    overdue: (status === 'Requested' && !!to && to < today) || (status === 'Scheduled' && !!to && isoDay_(r.scheduled_date || r.service_date) > to),
    paid_on: isoDay_(r.paid_on)
  };
  if (moneyAllowed_(user, r)) {
    card.amount_charged = r.amount_charged; card.payment_status = r.payment_status; card.advance_paid = r.advance_paid; card.advance_amount = r.advance_amount; card.final_amount = r.final_amount;
  } else card.money_hidden = true;
  return card;
}

// ---------- the one-time carry-over of the old service records ----------
// Adds only: the planned day of a Scheduled job is copied into scheduled_date; a job whose farmer has exactly one land is tied to that land;
// the kinds of service of the new flow are added to the list. Flag: Config services_flow_migrated.
function ensureServiceFlow_() {
  if (String(getConfig_('services_flow_migrated') || '') === 'Yes') return { skipped: true };
  return withLock_(() => {
    if (String(getConfig_('services_flow_migrated') || '') === 'Yes') return { skipped: true };
    const H = SCHEMA.Services;
    const sh = sheet_('Services');
    const last = sh.getLastRow();
    let linked = 0, dated = 0;
    if (last >= 2) {
      const landsBy = {};
      readColumns_('Fields', ['field_id', 'farmer_id', 'active']).forEach(l => { if (l.active === 'Yes') (landsBy[l.farmer_id] = landsBy[l.farmer_id] || []).push(l.field_id); });
      const c = n => H.indexOf(n);
      const cols = [c('land_id'), c('scheduled_date')];
      const from = Math.min(cols[0], cols[1]), to = Math.max(cols[0], cols[1]);
      const block = sh.getRange(2, 1, last - 1, H.length).getValues();
      const out = [];
      let changed = false;
      block.forEach(v => {
        const row = v.slice(from, to + 1);
        if (v[c('service_id')] !== '') {
          if (v[c('land_id')] === '' && (landsBy[v[c('farmer_id')]] || []).length === 1) { row[c('land_id') - from] = landsBy[v[c('farmer_id')]][0]; linked++; changed = true; }
          if (v[c('scheduled_date')] === '' && (v[c('status')] === 'Scheduled') && v[c('service_date')] !== '') { row[c('scheduled_date') - from] = isoDay_(v[c('service_date')]); dated++; changed = true; }
        }
        out.push(row);
      });
      if (changed) { touch_('Services'); sh.getRange(2, from + 1, out.length, to - from + 1).setValues(out); }
    }
    const have = serviceListValues_('service_type', true).map(x => x.toLowerCase());
    const add = FLOW_STARTER_TYPES_.filter(t => have.indexOf(t.toLowerCase()) === -1);
    if (add.length) appendObjects_('Lists', add.map(t => ({ list_name: 'service_type', value: t, active: 'Yes' })));
    setConfig_('services_flow_migrated', 'Yes', 'Old services carried over to the four-step flow (see ServiceFlow.gs)');
    audit_('migrate', 'Services', '', 'linked ' + linked + ' to a land, dated ' + dated + ' scheduled, added ' + add.length + ' kinds of service');
    return { linked: linked, dated: dated, added: add.length };
  });
}

// ---------- options ----------

function getServiceFlowOptions() {
  const user = requireFlowUser_();
  ensureServiceFlow_();
  const pilots = [];
  readAll_('Users').forEach(u => {
    if (u.active !== 'Yes' || hiddenRow_(u)) return;
    if (u.role === 'Pilot' || u.role === 'Admin' || u.role === 'Manager') pilots.push({ email: String(u.email).toLowerCase(), name: u.name, role: u.role });
  });
  return plain_({
    types: serviceListValues_('service_type'), crops: listsMap_().crop, drones: serviceListValues_('drone'), base_stations: serviceListValues_('base_station'),
    stations: stationList_(false).filter(s => !user.base_station || s.name === user.base_station), drone_list: droneList_(false).filter(d => !user.base_station || d.base_station === user.base_station).map(d => Object.assign(d, { pilot: dronePilots_()[d.name] || '' })),
    my_station: String(user.base_station || ''), my_drone: String(user.drone || ''),
    sources: REQUEST_SOURCES_, pilots: pilots.sort((a, b) => String(a.name).localeCompare(String(b.name))), today: localToday_(),
    me: { email: String(user.email).toLowerCase(), name: user.name, role: user.role }, powers: powersOf_(user)
  });
}

// ---------- step 1: request ----------

// old = the stored request when it is being changed: its owner check and its past days are then left alone (the land may have been sold, the window may have passed).
function cleanRequestItem_(it, i, farmerId, ctx, lists, types, old) {
  const n = 'Land ' + (i + 1);
  const land = ctx.lands[String(it.land_id || '')];
  if (!land || land.active !== 'Yes') throw new Error(n + ': choose one of the farmer\'s lands.');
  if (!old && String(land.farmer_id) !== farmerId) throw new Error(n + ': this land is not owned by this farmer now.');
  const crop = checkList_(clean_(it.crop), lists.crop, n + ' crop', '');
  if (!crop) throw new Error(n + ': choose the crop.');
  const type = checkList_(clean_(it.service_type), types, n + ' service', '');
  if (!type) throw new Error(n + ': choose the service.');
  let acres = cleanNumber_(it.acres === undefined || it.acres === '' ? land.acres : it.acres, n + ' acres', 0, MAX_SERVICE_ACRES);
  if (acres === '' || acres <= 0) throw new Error(n + ': acres must be more than 0.');
  let from = '', to = '', exact = 'No';
  if (String(it.exact_day || '').trim()) {
    to = from = flowDate_(it.exact_day, n + ' day', { notPast: !(old && isoDay_(old.window_to) === String(it.exact_day).slice(0, 10)) }); exact = 'Yes';
  } else {
    to = flowDate_(it.window_to, n + ' "before this day"', { required: true, notPast: !(old && isoDay_(old.window_to) === String(it.window_to).slice(0, 10)) });
    from = flowDate_(it.window_from, n + ' "from"', { notPast: !(old && isoDay_(old.window_from) === String(it.window_from || '').slice(0, 10)) });
    if (from && from > to) throw new Error(n + ': the first day is after the last day.');
  }
  return { land_id: land.field_id, crop: crop, service_type: type, acres: round2_(acres), window_from: from, window_to: to, exact_day: exact };
}

// input: { farmer_id, source, notes, items: [{ land_id, crop, service_type, acres?, window_to | exact_day, window_from? }] }
function createServiceRequest(input) {
  const user = requirePower_('service.request');
  return withLock_(() => {
    ensureServiceFlow_();
    input = input || {};
    const farmerId = String(input.farmer_id || '').trim();
    const e = farmerId ? indexEntry_(farmerId) : null;
    if (!e) throw new Error('Choose the farmer first.');
    if (e.v[14] !== 'Active') throw new Error('This farmer has been removed, so a request cannot be recorded.');
    const items = Array.isArray(input.items) ? input.items : [];
    if (!items.length) throw new Error('Choose at least one land.');
    if (items.length > FLOW_MAX_ITEMS_) throw new Error('A request can have at most ' + FLOW_MAX_ITEMS_ + ' lands.');
    const source = REQUEST_SOURCES_.indexOf(input.source) !== -1 ? input.source : 'Field officer';
    const station = cleanStation_(input.base_station, user, '');
    const ctx = flowContext_();
    const lists = listsMap_(), types = serviceListValues_('service_type');
    const clean = items.map((it, i) => cleanRequestItem_(it, i, farmerId, ctx, lists, types));
    const seen = {};
    clean.forEach((c, i) => { const k = c.land_id + '|' + c.service_type; if (seen[k]) throw new Error('Land ' + (i + 1) + ': the same service is listed twice for this land.'); seen[k] = true; });
    // an open request for the same land and service already exists
    const open = readColumns_('Services', ['service_id', 'land_id', 'service_type', 'status', 'farmer_id']).filter(r => r.farmer_id === farmerId && (r.status === 'Requested' || r.status === 'Scheduled'));
    clean.forEach((c, i) => { const twin = open.find(r => r.land_id === c.land_id && String(r.service_type) === c.service_type); if (twin) throw new Error('Land ' + (i + 1) + ': there is already an open request for this service (' + twin.service_id + ').'); });
    const ids = nextIds_('SV', 6, clean.length), group = nextId_('RQ', 6), today = localToday_(), me = String(user.email).toLowerCase();
    const rows = clean.map((c, i) => Object.assign({
      service_id: ids[i], farmer_id: farmerId, status: 'Requested', requested_date: today, service_type: c.service_type, crop: c.crop,
      land_id: c.land_id, request_group: group, request_source: source, requested_by: me, window_from: c.window_from, window_to: c.window_to, exact_day: c.exact_day,
      acres_requested: c.acres, request_notes: clean_(input.notes).slice(0, 300), base_station: station
    }, auditCols_(true)));
    appendObjects_('Services', rows);
    audit_('create', 'Services', group, farmerId + ' requested ' + rows.length + (rows.length === 1 ? ' service' : ' services') + ' (' + ids.join(', ') + ') at ' + station, { farmer_id: farmerId, land_id: clean.map(c => c.land_id).join(',') });
    return { request_group: group, service_ids: ids };
  });
}

// The base station of a job: the one chosen (or the person's own when they work from one); it must exist, and a person cannot use another station than theirs.
function cleanStation_(raw, user, current) {
  const stations = serviceListValues_('base_station');
  const mine = String((user && user.base_station) || '');
  const st = clean_(raw) || (current ? String(current) : mine);
  if (!st) throw new Error('Choose the base station that will handle this service.');
  if (stations.indexOf(st) === -1 && st !== String(current || '')) throw new Error('Choose the base station from the list.');
  if (mine && st !== mine) throw new Error('Not authorised: your account works from ' + mine + '.');
  return st;
}

function loadFlowRow_(serviceId) {
  const rec = findServiceRow_(String(serviceId || ''));
  if (!rec) throw new Error('Service not found.');
  return rec;
}

function saveFlowRow_(rec, patch, note) {
  const row = rec._archived ? restoreServiceRow_(rec.service_id) : rec;
  const obj = Object.assign({}, row, patch, auditCols_(false));
  writeRowObject_('Services', row._row, obj);
  const bits = [];
  Object.keys(patch).forEach(k => { const a = String(row[k] === undefined || row[k] === null ? '' : row[k]), b = String(patch[k] === undefined || patch[k] === null ? '' : patch[k]); if (a !== b) bits.push(k + ': ' + (a || '-') + ' > ' + (b || '-')); });
  audit_('update', 'Services', obj.service_id, note + (bits.length ? ' (' + bits.join('; ').slice(0, 400) + ')' : ''), { farmer_id: obj.farmer_id, land_id: obj.land_id });
  return obj;
}

// Changes an open request (crop, service, acres, the promised window, the note).
function updateServiceRequest(serviceId, patch) {
  const user = requirePower_('service.request');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (!stationOk_(user, rec)) throw new Error('Not authorised: this job belongs to another base station.');
    if (rec.status !== 'Requested') throw new Error('Only a request that has not been scheduled yet can be changed.');
    const p = patch || {};
    const ctx = flowContext_();
    const c = cleanRequestItem_({ land_id: rec.land_id, crop: p.crop === undefined ? rec.crop : p.crop, service_type: p.service_type === undefined ? rec.service_type : p.service_type, acres: p.acres === undefined ? rec.acres_requested : p.acres,
      exact_day: p.exact_day === undefined && p.window_to === undefined ? (String(rec.exact_day) === 'Yes' ? isoDay_(rec.window_to) : '') : p.exact_day, window_to: p.window_to === undefined ? isoDay_(rec.window_to) : p.window_to,
      window_from: p.window_from === undefined ? isoDay_(rec.window_from) : p.window_from }, 0, rec.farmer_id, ctx, listsMap_(), serviceListValues_('service_type'), rec);
    saveFlowRow_(rec, { crop: c.crop, service_type: c.service_type, acres_requested: c.acres, window_from: c.window_from, window_to: c.window_to, exact_day: c.exact_day,
      request_notes: p.notes === undefined ? rec.request_notes : clean_(p.notes).slice(0, 300), base_station: p.base_station === undefined ? rec.base_station : cleanStation_(p.base_station, user, rec.base_station) }, 'request changed');
    return { service_id: rec.service_id };
  });
}

function cancelService(serviceId, reason) {
  const user = requirePower_('service.request');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (!stationOk_(user, rec)) throw new Error('Not authorised: this job belongs to another base station.');
    if (rec.status !== 'Requested' && rec.status !== 'Scheduled') throw new Error('Only a request or a scheduled service can be cancelled.');
    const why = clean_(reason).slice(0, 200);
    if (!why) throw new Error('Say why it is cancelled.');
    saveFlowRow_(rec, { status: 'Cancelled', notes: clean_((rec.notes ? rec.notes + ' | ' : '') + 'Cancelled: ' + why).slice(0, 300) }, 'cancelled: ' + why);
    return { service_id: rec.service_id, status: 'Cancelled' };
  });
}

// ---------- step 2: scheduled ----------

// A request gets its day and time (or a scheduled service is moved to another day or time, as often as needed). opts: { time: 'HH:MM', note }.
// Moving a job to ANOTHER day takes it off its drone (the drone was chosen for the old day).
function scheduleService(serviceId, date, opts) {
  const user = requirePower_('service.schedule');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (!powerCovers_(user, 'service.schedule', rec)) throw new Error('Not authorised: this job belongs to another base station.');
    if (rec.status !== 'Requested' && rec.status !== 'Scheduled') throw new Error('Only a request or a scheduled service can be given a day.');
    const o = opts || {};
    const day = flowDate_(date, 'The day', { required: true, notPast: true });
    const time = String(o.time || '').trim();
    if (time && !isTime_(time)) throw new Error('The time is not valid: enter hours and minutes.');
    const patch = { status: 'Scheduled', scheduled_date: day, service_date: day, scheduled_time: time, scheduled_on: localToday_(), scheduled_by: String(user.email).toLowerCase() };
    const why = clean_(o.note).slice(0, 120);
    if (rec.status === 'Scheduled') {
      const was = isoDay_(rec.scheduled_date) || isoDay_(rec.service_date), wasTime = timeText_(rec.scheduled_time);
      if (was === day && wasTime === time) throw new Error('It is already scheduled for that day and time.');
      patch.schedule_notes = clean_((rec.schedule_notes ? rec.schedule_notes + ' | ' : '') + 'Moved from ' + was + (wasTime ? ' ' + wasTime : '') + ' to ' + day + (time ? ' ' + time : '') + (why ? ': ' + why : '')).slice(0, 300);
      if (was !== day) { patch.drone = ''; patch.stop_order = ''; patch.assigned_on = ''; patch.assigned_by = ''; patch.pilot_email = ''; patch.pilot_name = ''; }
    } else if (why) patch.schedule_notes = why;
    saveFlowRow_(rec, patch, 'scheduled for ' + day + (time ? ' ' + time : ''));
    const to = isoDay_(rec.window_to);
    return { service_id: rec.service_id, status: 'Scheduled', scheduled_date: day, late: !!to && day > to };
  });
}

// A scheduled service goes back to the requests (its day, time and drone are forgotten; the history of moves stays in its notes).
function unscheduleService(serviceId, note) {
  const user = requirePower_('service.schedule');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (!powerCovers_(user, 'service.schedule', rec)) throw new Error('Not authorised: this job belongs to another base station.');
    if (rec.status !== 'Scheduled') throw new Error('Only a scheduled service can go back to requested.');
    const was = isoDay_(rec.scheduled_date) || isoDay_(rec.service_date), why = clean_(note).slice(0, 120);
    saveFlowRow_(rec, { status: 'Requested', scheduled_date: '', service_date: '', scheduled_time: '', scheduled_on: '', scheduled_by: '', drone: '', stop_order: '', assigned_on: '', assigned_by: '', pilot_email: '', pilot_name: '',
      schedule_notes: clean_((rec.schedule_notes ? rec.schedule_notes + ' | ' : '') + 'Back to requested (was ' + was + ')' + (why ? ': ' + why : '')).slice(0, 300) }, 'back to requested');
    return { service_id: rec.service_id, status: 'Requested' };
  });
}

// ---------- the day plan: scheduled services given to a drone ----------

// assignments: [{ service_id, drone ('' takes the job off its drone), stop_order }]. Only scheduled services; the drone must work from the job's base station.
// The pilot of the job is the account that belongs to the drone (if there is one).
function assignJobs(assignments) {
  const user = requirePower_('service.assign');
  return withLock_(() => {
    const list = Array.isArray(assignments) ? assignments : [];
    if (!list.length) throw new Error('Nothing to assign.');
    if (list.length > 80) throw new Error('At most 80 jobs can be assigned at once.');
    const drones = droneList_(false), accounts = {}, me = String(user.email).toLowerCase();
    readAll_('Users').forEach(u => { if (u.active === 'Yes' && u.drone && !hiddenRow_(u)) accounts[String(u.drone)] = u; });
    const out = [];
    list.forEach(a => {
      const rec = loadFlowRow_(a && a.service_id);
      if (!powerCovers_(user, 'service.assign', rec)) throw new Error('Not authorised: ' + rec.service_id + ' belongs to another base station.');
      if (rec.status !== 'Scheduled') throw new Error(rec.service_id + ': only a scheduled service can be given to a drone.');
      const drone = clean_(a.drone);
      let patch;
      if (!drone) patch = { drone: '', stop_order: '', assigned_on: '', assigned_by: '', pilot_email: '', pilot_name: '' };
      else {
        const d = drones.find(x => x.name === drone);
        if (!d) throw new Error('Choose the drone from the list.');
        const st = String(rec.base_station || '');
        if (st && d.base_station && d.base_station !== st) throw new Error(drone + ' works from ' + d.base_station + ', not ' + st + '.');
        const acct = accounts[drone], order = Math.floor(Number(a.stop_order));
        patch = { drone: drone, stop_order: order > 0 ? order : '', assigned_on: rec.drone === drone && rec.assigned_on ? rec.assigned_on : localToday_(), assigned_by: me,
          pilot_email: acct ? String(acct.email).toLowerCase() : '', pilot_name: acct ? acct.name : '' };
        if (!st && d.base_station) patch.base_station = d.base_station;
      }
      saveFlowRow_(rec, patch, drone ? 'given to ' + drone : 'taken off its drone');
      out.push(rec.service_id);
    });
    return { service_ids: out };
  });
}

// ---------- step 3: completed ----------

// data: { service_date (the day it was done), start_time, end_time, pilot_email, drone, base_station, acres_covered, tanks, product_used, quantity_l, weather, crop, service_type, satisfaction?, notes }
function completeService(serviceId, data) {
  const user = requirePower_('service.complete');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (rec.status !== 'Scheduled' && rec.status !== 'Completed') throw new Error('Only a scheduled service can be completed.');
    if (!powerCovers_(user, 'service.complete', rec)) throw new Error('Not authorised: this job belongs to another pilot.');
    if (rec.status === 'Scheduled' && !rec.drone) throw new Error('Give this job to a drone first (Job assigning).');
    if (rec.status === 'Completed' && powerScope_(user, 'service.complete') === 'own' && Date.now() - new Date(rec.created_at).getTime() > PILOT_EDIT_DAYS * 86400000) throw new Error('Not authorised: a pilot can only correct their own records for ' + PILOT_EDIT_DAYS + ' days.');
    const d = data || {};
    const today = localToday_();
    const day = flowDate_(d.service_date || isoDay_(rec.scheduled_date) || isoDay_(rec.service_date), 'The day it was done', { required: true, notFuture: true });
    const req = isoDay_(rec.requested_date);
    if (req && day < req) throw new Error('The service cannot be dated before the day it was requested.');
    const start = String(d.start_time || '').trim(), end = String(d.end_time || '').trim();
    if (!isTime_(start) || !isTime_(end)) throw new Error('Enter the start time and the end time.');
    if (minutesOf_(end) <= minutesOf_(start)) throw new Error('The end time must be after the start time.');
    let pilotEmail = String(rec.pilot_email || ''), pilotName = String(rec.pilot_name || '');
    if (powerScope_(user, 'service.complete') === 'own') { pilotEmail = String(user.email).toLowerCase(); pilotName = user.name; }
    else if (d.pilot_email) {
      const row = findUserByEmail_(String(d.pilot_email).toLowerCase());
      if (!row || row.active !== 'Yes' || hiddenRow_(row) || row.role === 'DataEntry') throw new Error('Choose the pilot from the list.');
      pilotEmail = String(row.email).toLowerCase(); pilotName = row.name;
    }
    if (!pilotEmail && rec.drone) { const a = readAll_('Users').find(u => u.active === 'Yes' && String(u.drone || '') === String(rec.drone)); if (a) { pilotEmail = String(a.email).toLowerCase(); pilotName = a.name; } }
    if (!pilotEmail) throw new Error('Choose the pilot who did the job.');
    const lists = listsMap_();
    const crop = checkList_(clean_(d.crop || rec.crop), lists.crop, 'Crop', rec.crop);
    const type = checkList_(clean_(d.service_type || rec.service_type), serviceListValues_('service_type'), 'Service', rec.service_type);
    if (!crop || !type) throw new Error('Choose the crop and the service.');
    const acres = cleanNumber_(d.acres_covered, 'Acres sprayed', 0, MAX_SERVICE_ACRES);
    if (acres === '' || acres <= 0) throw new Error('Acres sprayed must be more than 0.');
    const tanks = cleanNumber_(d.tanks, 'Tanks', 0, 10000);
    let sat = '';
    if (d.satisfaction !== '' && d.satisfaction !== undefined && d.satisfaction !== null) { sat = Number(d.satisfaction); if (!Number.isInteger(sat) || sat < 1 || sat > 5) throw new Error('Satisfaction is a score from 1 to 5.'); }
    const patch = {
      status: 'Completed', service_date: day, start_time: start, end_time: end, duration_min: minutesOf_(end) - minutesOf_(start), pilot_email: pilotEmail, pilot_name: pilotName,
      drone: String(rec.drone || ''), base_station: String(rec.base_station || ''),
      crop: crop, service_type: type, acres_covered: round2_(acres), tanks: tanks, product_used: clean_(d.product_used).slice(0, 80), quantity_l: cleanNumber_(d.quantity_l, 'Quantity', 0, 100000),
      weather: clean_(d.weather).slice(0, 80), satisfaction: sat, notes: clean_(d.notes === undefined ? rec.notes : d.notes).slice(0, 300),
      completed_on: rec.status === 'Completed' ? rec.completed_on : today, completed_by: rec.status === 'Completed' ? rec.completed_by : String(user.email).toLowerCase()
    };
    if (!isoDay_(rec.scheduled_date) && rec.status === 'Scheduled') patch.scheduled_date = isoDay_(rec.service_date);
    saveFlowRow_(rec, patch, 'completed ' + patch.acres_covered + ' ac');
    return { service_id: rec.service_id, status: 'Completed' };
  });
}

// ---------- step 4: payment ----------

// data: { amount_charged (the total), advance: 'Yes'|'No', advance_amount, advance_date, final_amount, final_date, payment_method, payment_ref, payment_notes }
function recordPayment(serviceId, data) {
  const user = requirePower_('service.payment');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (rec.status === 'Cancelled') throw new Error('A payment cannot be entered for a cancelled service.');
    if (!powerCovers_(user, 'service.payment', rec)) throw new Error('Not authorised: this job belongs to another pilot.');
    const d = data || {};
    const total = cleanNumber_(d.amount_charged, 'The total amount', 0, 100000000);
    if (total === '') throw new Error('Enter the total amount (0 if it is free).');
    const req = isoDay_(rec.requested_date);
    const early = (v, l) => { if (req && v < req) throw new Error(l + ' cannot be before the day it was requested.'); return v; };
    const adv = String(d.advance) === 'Yes';
    let advAmt = '', advDate = '';
    if (adv) {
      advAmt = cleanNumber_(d.advance_amount, 'The advance', 0, 100000000);
      if (advAmt === '' || advAmt <= 0) throw new Error('Enter the advance amount.');
      advDate = early(flowDate_(d.advance_date, 'The day the advance was paid', { required: true, notFuture: true }), 'The advance day');
    }
    let finAmt = cleanNumber_(d.final_amount, 'The payment', 0, 100000000), finDate = '';
    if (finAmt !== '' && finAmt > 0) finDate = early(flowDate_(d.final_date, 'The day it was paid', { required: true, notFuture: true }), 'The payment day');
    else finAmt = '';
    const paid = round2_((Number(advAmt) || 0) + (Number(finAmt) || 0));
    if (paid > Number(total)) throw new Error('The money paid (' + paid + ') is more than the total (' + total + ').');
    const status = Number(total) === 0 ? 'Free' : (paid >= Number(total) ? 'Paid' : (paid > 0 ? 'Partly paid' : 'Unpaid'));
    const last = [advDate, finDate].filter(Boolean).sort().pop() || '';
    saveFlowRow_(rec, {
      amount_charged: round2_(total), payment_status: status, advance_paid: adv ? 'Yes' : 'No', advance_amount: advAmt, advance_date: advDate, final_amount: finAmt, final_date: finDate,
      payment_method: clean_(d.payment_method).slice(0, 40), payment_ref: clean_(d.payment_ref).slice(0, 60), payment_notes: clean_(d.payment_notes).slice(0, 200), paid_on: last, paid_by: String(user.email).toLowerCase()
    }, 'payment ' + status);
    return { service_id: rec.service_id, payment_status: status, paid: paid, total: round2_(total) };
  });
}

// ---------- reading: list, map, one service ----------

function flowFilter_(input) {
  const f = input || {};
  const out = { stage: clean_(f.stage), from: flowDate_(f.from, 'From', {}), to: flowDate_(f.to, 'To', {}), district: clean_(f.district).slice(0, 60), ds_division: clean_(f.ds_division).slice(0, 60),
    type: clean_(f.service_type).slice(0, 80), crop: clean_(f.crop).slice(0, 60), payment: clean_(f.payment), q: clean_(f.q).toLowerCase().slice(0, 60), farmer_id: clean_(f.farmer_id).slice(0, 20),
    land_id: clean_(f.land_id).slice(0, 20), pilot: clean_(f.pilot_email).toLowerCase(), overdue: f.overdue === true || f.overdue === 'Yes',
    base_station: clean_(f.base_station).slice(0, 40), drone: clean_(f.drone).slice(0, 40), assigned: f.assigned === 'Yes' || f.assigned === 'No' ? f.assigned : '' };
  if (out.from && out.to && out.from > out.to) throw new Error('"From" is after "To".');
  if (out.stage && ['Requested', 'Scheduled', 'Completed', 'Cancelled', 'Active', 'Payable'].indexOf(out.stage) === -1) throw new Error('Unknown stage.');
  if (out.payment && ['Paid', 'Partly paid', 'Unpaid', 'Free', 'None'].indexOf(out.payment) === -1) throw new Error('Unknown payment state.');
  return out;
}

// The day a service counts under for a time period: requests by their promised window (any overlap), the others by their own day.
function flowInPeriod_(r, f) {
  if (!f.from && !f.to) return true;
  const s = String(r.status);
  if (s === 'Requested') {
    const lo = isoDay_(r.window_from) || isoDay_(r.requested_date), hi = isoDay_(r.window_to) || lo;
    return (!f.to || lo <= f.to) && (!f.from || hi >= f.from);
  }
  const day = s === 'Scheduled' ? (isoDay_(r.scheduled_date) || isoDay_(r.service_date)) : (s === 'Completed' ? isoDay_(r.service_date) : isoDay_(r.requested_date));
  return !!day && (!f.from || day >= f.from) && (!f.to || day <= f.to);
}

function flowMatches_(r, f, card, user) {
  // a person sees only their base station's jobs, and a drone account only its drone's jobs (see Powers.gs)
  if (!stationOk_(user, r)) return false;
  if (user.drone && String(r.drone || '') !== user.drone && String(r.pilot_email || '').toLowerCase() !== String(user.email).toLowerCase()) return false;
  if (f.base_station && String(r.base_station || '') !== f.base_station) return false;
  if (f.drone && String(r.drone || '') !== f.drone) return false;
  if (f.assigned === 'Yes' && !r.drone) return false;
  if (f.assigned === 'No' && r.drone) return false;
  // Active = still to be done (requested or scheduled); Payable = a payment can be entered (scheduled or completed)
  if (f.stage === 'Active' ? (r.status !== 'Requested' && r.status !== 'Scheduled') : f.stage === 'Payable' ? (r.status === 'Cancelled') : (f.stage && r.status !== f.stage)) return false;
  if (!flowInPeriod_(r, f)) return false;
  if (f.type && String(r.service_type) !== f.type) return false;
  if (f.crop && String(r.crop) !== f.crop) return false;
  if (f.farmer_id && r.farmer_id !== f.farmer_id) return false;
  if (f.land_id && r.land_id !== f.land_id) return false;
  if (f.pilot && String(r.pilot_email).toLowerCase() !== f.pilot) return false;
  if (f.district && card.district !== f.district) return false;
  if (f.ds_division && card.ds_division !== f.ds_division) return false;
  if (f.overdue && !card.overdue) return false;
  if (f.payment) {
    if (!moneyAllowed_(user, r)) return false;
    const p = String(r.payment_status || '');
    if (f.payment === 'None' ? p !== '' : p !== f.payment) return false;
  }
  if (f.q && [card.farmer_name, card.farmer_id, card.land_label, card.land_id, card.service_id, card.village].join(' ').toLowerCase().indexOf(f.q) === -1) return false;
  return true;
}

function flowSort_(rows, stage) {
  // requests: the most urgent promise first; scheduled: the nearest day first; everything else: the latest first
  const key = c => (c.status === 'Requested' ? (c.window_to || '9999') : c.status === 'Scheduled' ? (c.scheduled_date || '9999') : (c.service_date || c.requested_date || ''));
  const asc = stage === 'Requested' || stage === 'Scheduled' || stage === 'Active';      // (Payable: latest first, like the history)
  return rows.sort((a, b) => (asc ? key(a).localeCompare(key(b)) : key(b).localeCompare(key(a))) || String(a.service_id).localeCompare(String(b.service_id)));
}

function flowSummary_(cards) {
  const by = { Requested: 0, Scheduled: 0, Completed: 0, Cancelled: 0 }, acres = { Requested: 0, Scheduled: 0, Completed: 0, Cancelled: 0 };
  const district = {}, type = {};
  let overdue = 0, unlocated = 0;
  cards.forEach(c => {
    by[c.status] = (by[c.status] || 0) + 1; acres[c.status] = round2_((acres[c.status] || 0) + c.acres);
    const d = c.district || 'Not recorded';
    district[d] = district[d] || { district: d, services: 0, acres: 0 }; district[d].services++; district[d].acres = round2_(district[d].acres + c.acres);
    const t = c.service_type || 'Not recorded'; type[t] = (type[t] || 0) + 1;
    if (c.overdue) overdue++;
    if (!c.located) unlocated++;
  });
  return { total: cards.length, by_stage: by, acres_by_stage: acres, overdue: overdue, unlocated: unlocated,
    by_district: Object.keys(district).map(k => district[k]).sort((a, b) => b.services - a.services),
    by_type: Object.keys(type).map(k => ({ name: k, services: type[k] })).sort((a, b) => b.services - a.services) };
}

// Everything the list screens need: the services that match the filters, as cards, the figures over ALL of them and (for the map) their pins.
function flowRun_(input, withPoints, cap) {
  const user = requireFlowUser_();
  ensureServiceFlow_();
  const f = flowFilter_(input);
  const ctx = flowContext_(), today = localToday_();
  const all = readColumns_('Services', FLOW_COLS_);
  const cards = [];
  all.forEach(r => {
    const card = flowCard_(r, ctx, user, today);
    // a person who has only the 'own' scope for completion or payment sees just those jobs in the lists meant for them: the caller asks with f.pilot
    if (flowMatches_(r, f, card, user)) cards.push(card);
  });
  flowSort_(cards, f.stage);
  const out = { rows: cards.slice(0, Number(input && input.limit) > 0 ? Math.min(Number(input.limit), cap || FLOW_LIST_LIMIT_) : (cap || FLOW_LIST_LIMIT_)), total: cards.length, truncated: cards.length > (cap || FLOW_LIST_LIMIT_), summary: flowSummary_(cards), today: today };
  if (withPoints) out.points = cards.filter(c => c.located).slice(0, FLOW_MAP_POINTS_).map(c => ({ id: c.service_id, lat: c.latitude, lng: c.longitude, status: c.status, acres: c.acres, type: c.service_type, overdue: c.overdue, district: c.district }));
  return out;
}

function listServiceFlow(filter) { return plain_(flowRun_(filter, false)); }

// The Reports table: the same filters as the lists, but up to 5000 rows and no map. Needs the report power.
const REPORT_ROWS_ = 5000;
function getServiceTable(filter) {
  requirePower_('report.view');
  const f = Object.assign({}, filter || {}, { limit: REPORT_ROWS_ });
  return plain_(flowRun_(f, false, REPORT_ROWS_));
}
function getServiceMap(filter) { return plain_(flowRun_(filter, true)); }

// The road of one service: its nodes, the days between them and what the signed-in person may do with it now.
function getServiceRoad(serviceId) {
  const user = requireFlowUser_();
  ensureServiceFlow_();
  const rec = loadFlowRow_(serviceId);
  if (!stationOk_(user, rec) || (user.drone && String(rec.drone || '') !== user.drone && String(rec.pilot_email || '').toLowerCase() !== String(user.email).toLowerCase())) throw new Error('Not authorised: this job is not in your base station.');
  const ctx = flowContext_(), today = localToday_();
  const card = flowCard_(rec, ctx, user, today);
  const s = String(rec.status);
  const sched = isoDay_(rec.scheduled_date) || (s === 'Scheduled' || s === 'Completed' ? isoDay_(rec.service_date) : '');
  const money = moneyAllowed_(user, rec);
  const pay = String(rec.payment_status || '');
  const nodes = [{ key: 'requested', label: 'Requested', state: 'done', date: isoDay_(rec.requested_date), by: rec.requested_by, note: windowText_(rec) }];
  if (s === 'Cancelled') nodes.push({ key: 'cancelled', label: 'Cancelled', state: 'cancelled', date: '', note: String(rec.notes || '') });
  else {
    nodes.push({ key: 'scheduled', label: 'Scheduled', state: s === 'Requested' ? 'next' : 'done', date: sched, by: rec.scheduled_by, note: rec.schedule_notes || '', late: !!sched && !!isoDay_(rec.window_to) && sched > isoDay_(rec.window_to) });
    nodes.push({ key: 'assigned', label: 'Drone assigned', state: rec.drone ? 'done' : (s === 'Scheduled' ? 'next' : 'todo'), date: isoDay_(rec.assigned_on), by: rec.assigned_by, note: String(rec.drone || '') });
    nodes.push({ key: 'completed', label: 'Completed', state: s === 'Completed' ? 'done' : (s === 'Scheduled' ? 'next' : 'todo'), date: s === 'Completed' ? isoDay_(rec.service_date) : '', by: rec.completed_by, note: s === 'Completed' ? (Number(rec.acres_covered) || 0) + ' acres' : '' });
    nodes.push(money ? { key: 'paid', label: pay === 'Paid' ? 'Paid in full' : (pay === 'Partly paid' ? 'Advance paid' : (pay === 'Free' ? 'No charge' : 'Payment')), state: (pay === 'Paid' || pay === 'Free') ? 'done' : (pay === 'Partly paid' ? 'partial' : (s === 'Completed' ? 'next' : 'todo')),
      date: isoDay_(rec.paid_on), by: rec.paid_by, note: '' } : { key: 'paid', label: 'Payment', state: 'hidden', date: '', note: '' });
  }
  const days = { request_to_schedule: daysBetween_(rec.requested_date, rec.scheduled_on || sched), request_to_done: s === 'Completed' ? daysBetween_(rec.requested_date, rec.service_date) : null,
    done_to_paid: pay === 'Paid' && s === 'Completed' ? daysBetween_(rec.service_date, rec.paid_on) : null,
    total: pay === 'Paid' ? daysBetween_(rec.requested_date, rec.paid_on) : (s === 'Completed' ? daysBetween_(rec.requested_date, rec.service_date) : null),
    open: s === 'Requested' || s === 'Scheduled' ? daysBetween_(rec.requested_date, today) : null,
    late_by: s === 'Completed' && isoDay_(rec.window_to) && isoDay_(rec.service_date) > isoDay_(rec.window_to) ? daysBetween_(rec.window_to, rec.service_date) : null };
  const detail = stripRow_(rec); delete detail._archived;
  ['requested_date', 'service_date', 'window_from', 'window_to', 'scheduled_date', 'scheduled_on', 'completed_on', 'advance_date', 'final_date', 'paid_on'].forEach(k => { detail[k] = isoDay_(detail[k]); });
  detail.start_time = timeText_(detail.start_time); detail.end_time = timeText_(detail.end_time);
  if (!money) SERVICE_MONEY_COLS_.forEach(k => { detail[k] = ''; });
  return plain_({
    card: card, nodes: nodes, days: days, detail: detail, today: today,
    can: {
      edit_request: s === 'Requested' && hasPower_(user, 'service.request'), cancel: (s === 'Requested' || s === 'Scheduled') && hasPower_(user, 'service.request'),
      schedule: (s === 'Requested' || s === 'Scheduled') && hasPower_(user, 'service.schedule'),
      complete: (s === 'Scheduled' || s === 'Completed') && (s === 'Completed' || !!rec.drone) && hasPower_(user, 'service.complete') && powerCovers_(user, 'service.complete', rec),
      payment: s !== 'Cancelled' && hasPower_(user, 'service.payment') && powerCovers_(user, 'service.payment', rec)
    }
  });
}

// ---------- bills ----------

// Issues (or shows again) the bill of a service. kind: 'final' (the individual payment bill with every detail of the job) or 'advance' (the advance payment bill).
// The bill number is made the first time and kept, so printing again gives the same number. Returns everything the bill shows.
function issueBill(serviceId, kind) {
  const user = requirePower_('service.payment');
  return withLock_(() => {
    const rec = loadFlowRow_(serviceId);
    if (!powerCovers_(user, 'service.payment', rec)) throw new Error('Not authorised: this job belongs to another base station or drone.');
    if (kind !== 'advance' && kind !== 'final') throw new Error('Unknown bill.');
    if (rec.status === 'Cancelled') throw new Error('A cancelled service has no bill.');
    const adv = kind === 'advance';
    if (adv && String(rec.advance_paid) !== 'Yes') throw new Error('No advance has been entered for this service.');
    if (!adv && String(rec.payment_status || '') === '') throw new Error('Enter the payment first, then print the bill.');
    let no = String(adv ? rec.advance_bill_no : rec.bill_no || ''), created = false, row = rec;
    if (!no) {
      no = nextId_(adv ? 'AB' : 'BL', 6); created = true;
      row = saveFlowRow_(rec, adv ? { advance_bill_no: no, billed_on: localToday_() } : { bill_no: no, billed_on: localToday_() }, (adv ? 'advance bill ' : 'bill ') + no + ' issued');
    } else audit_('view', 'Services', rec.service_id, (adv ? 'advance bill ' : 'bill ') + no + ' printed again', { farmer_id: rec.farmer_id, land_id: rec.land_id });
    const farmer = readColumns_('Farmers', ['farmer_id', 'full_name', 'phone_primary', 'address', 'village', 'ds_division', 'district']).find(f => f.farmer_id === row.farmer_id) || {};
    const land = row.land_id ? (readColumns_('Fields', ['field_id', 'land_name', 'acres', 'village', 'ds_division', 'district', 'tank']).find(l => l.field_id === row.land_id) || null) : null;
    const total = Number(row.amount_charged) || 0, advAmt = Number(row.advance_amount) || 0, finAmt = Number(row.final_amount) || 0;
    return plain_({
      kind: kind, bill_no: no, issued_on: isoDay_(row.billed_on) || localToday_(), reissued: !created, prepared_by: user.name,
      company: { name: String(getConfig_('bill_company') || 'CAFT drone spraying service'), address: String(getConfig_('bill_address') || ''), phone: String(getConfig_('bill_phone') || ''), footer: String(getConfig_('bill_footer') || 'Thank you.') },
      farmer: { id: farmer.farmer_id || row.farmer_id, name: farmer.full_name || '', phone: farmer.phone_primary || '', address: [farmer.address, farmer.village, farmer.ds_division, farmer.district].filter(Boolean).join(', ') },
      land: land ? { id: land.field_id, name: land.land_name || '', acres: Number(land.acres) || 0, place: [land.village, land.ds_division, land.district].filter(Boolean).join(', '), tank: land.tank || '' } : null,
      service: { id: row.service_id, type: row.service_type, crop: row.crop, status: row.status, requested: isoDay_(row.requested_date), scheduled: isoDay_(row.scheduled_date), done: row.status === 'Completed' ? isoDay_(row.service_date) : '',
        start: timeText_(row.start_time), end: timeText_(row.end_time), acres_requested: Number(row.acres_requested) || 0, acres_done: Number(row.acres_covered) || 0, tanks: row.tanks, product: row.product_used, quantity_l: row.quantity_l,
        drone: row.drone, pilot: row.pilot_name, base_station: row.base_station, weather: row.weather },
      money: { total: total, advance_paid: String(row.advance_paid) === 'Yes', advance_amount: advAmt, advance_date: isoDay_(row.advance_date), final_amount: finAmt, final_date: isoDay_(row.final_date), method: row.payment_method, ref: row.payment_ref,
        paid: round2_(advAmt + finAmt), balance: round2_(total - advAmt - finAmt), status: row.payment_status }
    });
  });
}

// ---- ServiceReportData.gs
// Numbers for the Service report screen, the best-customer ranking, and the service export. Counting happens here, so the
// browser only receives a small summary however many services there are.
//
// A report is: a date range, optional service kinds / pilots / crops, an "area" (the same filters as the farmer finder: district,
// division, origin boxes such as a tank or Govi committee, saved groups), and a way to group the answer.

const REPORT_GROUP_LIMIT = 150;
const REPORT_TOP_LIMIT = 50;
const REPORT_MAX_MONTHS = 36;
const REPORT_RANKS = ['acres', 'services', 'amount', 'satisfaction'];
const FARMER_GROUPS = ['district', 'division'];

function originLabel_(S, option) {
  return String(option.path).split('>').map(id => (S.optionById[id] ? S.optionById[id].label : id)).join(' › ');
}

// What the area picker needs: districts, divisions, every origin box (with its full route as the label) and the saved groups.
function getAreaOptions() {
  requireRole_(['Admin', 'Manager']);
  const S = originStructure_();
  const divisions = [];
  const seen = {};
  indexLoad_().entries.forEach(e => { const d = e.v[10]; if (d && !seen[d]) { seen[d] = true; divisions.push(d); } });
  divisions.sort();
  const origin = S.options.filter(o => o.active === 'Yes').map(o => ({ id: o.option_id, question_id: o.question_id, label: originLabel_(S, o) }))
    .sort((a, b) => a.label.localeCompare(b.label));
  return plain_({
    districts: listsMap_().district, divisions: divisions, origin: origin,
    origin_questions: S.origin.map(q => ({ question_id: q.question_id, label: q.label })),
    segments: listSegments()
  });
}

function cleanReportInput_(input, S) {
  const f = input || {};
  const out = {
    from: cleanDate_(f.from, 'From'), to: cleanDate_(f.to, 'To'),
    service_types: cleanList_(f.service_types), pilots: cleanList_(f.pilots).map(s => s.toLowerCase()), crops: cleanList_(f.crops),
    area: cleanFilters_(f.area || [], S.optionById), status: clean_(f.status), group_by: String(f.group_by || 'division'), rank_by: String(f.rank_by || 'acres')
  };
  if (out.from && out.to && out.from > out.to) throw new Error('"From" is after "To".');
  if (out.status && SERVICE_STATUSES.indexOf(out.status) === -1) throw new Error('Unknown status.');
  const g = out.group_by;
  const okGroup = ['district', 'division', 'service_type', 'pilot', 'crop', 'month'].indexOf(g) !== -1 || (/^origin:Q\d+$/.test(g) && S.questionById[g.slice(7)]);
  if (!okGroup) throw new Error('Choose how to group the report.');
  if (REPORT_RANKS.indexOf(out.rank_by) === -1) throw new Error('Choose how to rank the customers.');
  return out;
}

// The names of the group(s) a service falls into. A farmer who chose several boxes under one question counts in each.
function reportGroupNames_(groupBy, entry, row, S) {
  switch (groupBy) {
    case 'district': return [entry && entry.v[9] ? entry.v[9] : '(not recorded)'];
    case 'division': return [entry && entry.v[10] ? entry.v[10] : '(not recorded)'];
    case 'service_type': return [row.service_type || '(not recorded)'];
    case 'pilot': return [row.pilot_name || row.pilot_email || '(not recorded)'];
    case 'crop': return [row.crop || '(not recorded)'];
    case 'month': return [serviceDay_(row).slice(0, 7) || '(no date)'];
    default: {
      const qid = groupBy.slice(7);
      const names = [];
      (entry ? entry.a : []).forEach(x => { const o = x[1] === qid && x[2] ? S.optionById[x[2]] : null; if (o) names.push(originLabel_(S, o)); });
      return names.length ? names : ['(not recorded)'];
    }
  }
}

// The farmers an area filter lets through, as { id: index entry }. With no area filter that is everyone.
function reportFarmers_(f) {
  const view = indexLoad_();
  if (!f.area.length) return view.byId;
  const ctx = finderContext_();
  const filters = f.area.some(x => x.type === 'status') ? f.area : f.area.concat([{ type: 'status', value: 'all' }]);
  const allowed = {};
  ctx.farmers.forEach(fm => { if (matchFarmer_(fm, filters, ctx)) allowed[fm.farmer_id] = view.byId[fm.farmer_id]; });
  return allowed;
}

// The service columns the report works from; the export wants every column (wide = true)
const REPORT_COLS_ = ['service_id', 'farmer_id', 'status', 'requested_date', 'service_date', 'duration_min', 'pilot_name', 'pilot_email', 'service_type', 'crop', 'acres_covered', 'amount_charged', 'satisfaction'];
function reportRows_(f, allowed, wide) {
  const wantStatus = f.status || '';
  const live = wide ? readAll_('Services') : readColumns_('Services', REPORT_COLS_);
  // old jobs that moved to the archive: only the months of the chosen dates are read (nothing while nothing is archived)
  const all = live.concat(withoutLiveIds_(archivedServiceRows_(f.from, f.to), live));
  return all.filter(r => {
    if (!allowed[r.farmer_id]) return false;
    if (wantStatus ? String(r.status) !== wantStatus : false) return false;
    const day = serviceDay_(r);
    if (f.from && (!day || day < f.from)) return false;
    if (f.to && (!day || day > f.to)) return false;
    if (f.service_types.length && f.service_types.indexOf(String(r.service_type)) === -1) return false;
    if (f.pilots.length && f.pilots.indexOf(String(r.pilot_email).toLowerCase()) === -1) return false;
    if (f.crops.length && f.crops.indexOf(String(r.crop)) === -1) return false;
    return true;
  });
}

function monthsBetween_(first, last, noCap) {
  const out = [];
  let y = Number(first.slice(0, 4)), m = Number(first.slice(5, 7));
  const ey = Number(last.slice(0, 4)), em = Number(last.slice(5, 7));
  while ((y < ey || (y === ey && m <= em)) && (noCap || out.length < REPORT_MAX_MONTHS)) {
    out.push(y + '-' + ('0' + m).slice(-2));
    m++; if (m > 12) { m = 1; y++; }
  }
  return out;
}

function getServiceReport(input) {
  requireRole_(['Admin', 'Manager']);
  const S = originStructure_();
  const f = cleanReportInput_(input, S);
  f.status = 'Completed';
  const allowed = reportFarmers_(f);
  const rows = reportRows_(f, allowed);
  const byId = indexLoad_().byId;

  const farmerStats = {};
  const groups = {};
  const month = {};
  const type = {}, pilot = {}, crop = {};
  const stars = [0, 0, 0, 0, 0];
  let acres = 0, minutes = 0, flownAcres = 0, amount = 0, rated = 0, ratingSum = 0;
  const addTo = (map, name, r) => {
    const g = map[name] = map[name] || { name: name, services: 0, acres: 0, amount: 0, farmers: {}, rated: 0, ratingSum: 0 };
    g.services++; g.acres += Number(r.acres_covered) || 0; g.amount += Number(r.amount_charged) || 0; g.farmers[r.farmer_id] = true;
    if (Number(r.satisfaction)) { g.rated++; g.ratingSum += Number(r.satisfaction); }
  };
  rows.forEach(r => {
    const e = byId[r.farmer_id];
    const a = Number(r.acres_covered) || 0;
    acres += a; amount += Number(r.amount_charged) || 0;
    if (Number(r.duration_min) > 0) { minutes += Number(r.duration_min); flownAcres += a; }
    const sat = Number(r.satisfaction);
    if (sat >= 1 && sat <= 5) { rated++; ratingSum += sat; stars[sat - 1]++; }
    const fs = farmerStats[r.farmer_id] = farmerStats[r.farmer_id] || { farmer_id: r.farmer_id, services: 0, acres: 0, amount: 0, rated: 0, ratingSum: 0, last: '' };
    fs.services++; fs.acres += a; fs.amount += Number(r.amount_charged) || 0; fs.last = serviceDay_(r) > fs.last ? serviceDay_(r) : fs.last;
    if (sat) { fs.rated++; fs.ratingSum += sat; }
    reportGroupNames_(f.group_by, e, r, S).forEach(n => addTo(groups, n, r));
    addTo(type, r.service_type || '(not recorded)', r);
    addTo(pilot, r.pilot_name || r.pilot_email || '(not recorded)', r);
    addTo(crop, r.crop || '(not recorded)', r);
    const m = serviceDay_(r).slice(0, 7);
    if (m) { month[m] = month[m] || { month: m, services: 0, acres: 0 }; month[m].services++; month[m].acres += a; }
  });

  // How many registered farmers are in each group, so a group's reach (served / registered) can be shown.
  const registered = {};
  if (FARMER_GROUPS.indexOf(f.group_by) !== -1 || /^origin:/.test(f.group_by)) {
    Object.keys(allowed).forEach(id => {
      const e = allowed[id];
      if (!e || e.v[14] !== 'Active') return;
      reportGroupNames_(f.group_by, e, {}, S).forEach(n => { registered[n] = (registered[n] || 0) + 1; });
    });
  }
  const shape = g => ({ name: g.name, services: g.services, farmers: Object.keys(g.farmers).length, acres: round2_(g.acres), amount: Math.round(g.amount),
    avg_satisfaction: g.rated ? round2_(g.ratingSum / g.rated) : null, registered: registered[g.name] === undefined ? null : registered[g.name] });
  const byAcres = (a, b) => b.acres - a.acres || b.services - a.services || String(a.name).localeCompare(String(b.name));
  const groupList = Object.keys(groups).map(k => shape(groups[k]));
  if (f.group_by === 'month') groupList.sort((a, b) => String(a.name).localeCompare(String(b.name))); else groupList.sort(byAcres);
  // Groups with registered farmers but no service yet matter too: they are the places still to reach.
  if (Object.keys(registered).length) Object.keys(registered).forEach(n => { if (!groups[n]) groupList.push({ name: n, services: 0, farmers: 0, acres: 0, amount: 0, avg_satisfaction: null, registered: registered[n] }); });

  const rankKey = { acres: 'acres', services: 'services', amount: 'amount', satisfaction: 'avg' }[f.rank_by];
  const top = Object.keys(farmerStats).map(id => {
    const s = farmerStats[id], e = byId[id];
    const groupNames = FARMER_GROUPS.indexOf(f.group_by) !== -1 || /^origin:/.test(f.group_by) ? reportGroupNames_(f.group_by, e, {}, S) : [];
    return { farmer_id: id, full_name: e ? e.v[1] : id, phone_primary: e ? e.v[7] : '', place: e ? [e.v[11], e.v[10]].filter(Boolean).join(', ') : '', group: groupNames.join(' · '),
      services: s.services, acres: round2_(s.acres), amount: Math.round(s.amount), avg: s.rated ? round2_(s.ratingSum / s.rated) : 0, last: s.last };
  }).sort((a, b) => b[rankKey] - a[rankKey] || b.acres - a.acres || b.services - a.services || a.full_name.localeCompare(b.full_name)).slice(0, REPORT_TOP_LIMIT);

  const monthKeys = Object.keys(month).sort();
  // at most REPORT_MAX_MONTHS months are drawn: when the history is longer it is the NEWEST months that are kept (the older ones are still in the totals)
  const lastMonth = monthKeys.length ? monthKeys[monthKeys.length - 1] : '';
  const firstShown = monthKeys.length ? (monthsBetween_(monthKeys[0], lastMonth, true).slice(-REPORT_MAX_MONTHS)[0]) : '';
  const monthList = monthKeys.length ? monthsBetween_(firstShown, lastMonth).map(k => ({ month: k, services: month[k] ? month[k].services : 0, acres: month[k] ? round2_(month[k].acres) : 0 })) : [];
  const servedIds = Object.keys(farmerStats);
  const inArea = Object.keys(allowed).filter(id => allowed[id] && allowed[id].v[14] === 'Active').length;
  // the work of a removed farmer still counts as work done, but "served of registered" only counts farmers who are still registered (so it never passes 100%)
  const servedActive = servedIds.filter(id => allowed[id] && allowed[id].v[14] === 'Active').length;
  const list = map => Object.keys(map).map(k => shape(map[k])).sort(byAcres);

  return plain_({
    totals: { services: rows.length, farmers: servedIds.length, acres: round2_(acres), hours: round2_(minutes / 60), acres_per_hour: minutes > 0 ? round2_(flownAcres / (minutes / 60)) : null,
      amount: Math.round(amount), avg_satisfaction: rated ? round2_(ratingSum / rated) : null, rated: rated,
      repeat_farmers: servedIds.filter(id => farmerStats[id].services >= 2).length, acres_per_service: rows.length ? round2_(acres / rows.length) : 0 },
    reach: { registered: inArea, served: servedActive, share: inArea ? Math.round(servedActive / inArea * 1000) / 10 : 0 },
    by_month: monthList, groups: groupList.slice(0, REPORT_GROUP_LIMIT), groups_truncated: groupList.length > REPORT_GROUP_LIMIT,
    by_type: list(type), by_pilot: list(pilot), by_crop: list(crop), stars: stars, top: top, group_by: f.group_by, rank_by: f.rank_by
  });
}

// The service log as a CSV for Excel: one line per service, with the farmer's place and origin.
function exportServices(input) {
  const user = requireRole_(['Admin', 'Manager']);
  const S = originStructure_();
  const f = cleanReportInput_(input, S);
  const allowed = reportFarmers_(f);
  const rows = sortServices_(reportRows_(f, allowed, true).map(r => serviceOut_(r, user)));
  const byId = indexLoad_().byId;
  const header = ['Service ID', 'Farmer ID', 'Farmer', 'Phone', 'District', 'DS division', 'Village', 'Origin', 'Status', 'Requested date', 'Service date', 'Start', 'End', 'Minutes',
    'Pilot', 'Drone', 'Service', 'Crop', 'Acres covered', 'Product', 'Litres', 'Amount (Rs)', 'Payment', 'Satisfaction (1-5)', 'Feedback', 'Notes'];
  const lines = [header.map(csvCell_).join(',')];
  rows.forEach(r => {
    const e = byId[r.farmer_id];
    const origin = e ? e.a.map(x => (x[2] && S.optionById[x[2]] ? originLabel_(S, S.optionById[x[2]]) : '')).filter(Boolean).join(' | ') : '';
    lines.push([r.service_id, r.farmer_id, e ? e.v[1] : '', e ? phoneForCsv_(e.v[7]) : '', e ? e.v[9] : '', e ? e.v[10] : '', e ? e.v[11] : '', origin, r.status, r.requested_date, r.service_date,
      r.start_time, r.end_time, r.duration_min, r.pilot_name, r.drone, r.service_type, r.crop, r.acres_covered, r.product_used, r.quantity_l, r.amount_charged, r.payment_status,
      r.satisfaction, r.feedback, r.notes].map(csvCell_).join(','));
  });
  audit_('export', 'Services', '', rows.length + ' services exported; filters: ' + JSON.stringify(f).slice(0, 400));
  return { csv: lines.join('\r\n'), count: rows.length };
}

// ---- Services.gs
// The service log: every spraying job (or booking) CAFT does for a farmer, who flew it, how big it was and how the farmer felt about it.
// Pilots record their own jobs; managers and admins can record and correct any; everyone who can see a farmer's profile sees that
// farmer's history. Reports and exports are in ServiceReportData.gs.

const SERVICE_STATUSES = ['Requested', 'Scheduled', 'Completed', 'Cancelled'];
const PAYMENT_STATUSES = ['Paid', 'Partly paid', 'Unpaid', 'Free'];
const SERVICE_LISTS = [['service_type', 'Kinds of service']];       // (drones and base stations have their own tabs, see Org.gs)
const SERVICE_ROLES = ['Admin', 'Manager', 'Pilot'];
const MAX_SERVICE_ACRES = 5000;
const LOCAL_OFFSET_MINUTES = 330;     // Sri Lanka time (UTC+5:30): the "today" a pilot means, whatever the server clock says
const PILOT_EDIT_DAYS = 7;            // a pilot can correct their own records for this many days
const SERVICE_LIST_LIMIT = 300;       // rows shown in the service log screen
const SERVICE_LIST_COLS_ = ['service_id', 'farmer_id', 'status', 'requested_date', 'service_date', 'start_time', 'duration_min', 'pilot_email', 'service_type', 'crop', 'acres_covered', 'amount_charged', 'satisfaction'];   // what the log screen needs from every record
const RECENT_SERVICE_READ = 400;     // how far back from the end of the tab "recent services" looks

function requireServiceUser_() { return requireRole_(SERVICE_ROLES); }

// While a save that waited on a phone is replayed (see submitOp), "today" is the day the person pressed save, so a day that was fine then is fine now.
var REPLAY_DAY_ = '';
function localToday_() { return REPLAY_DAY_ || new Date(Date.now() + LOCAL_OFFSET_MINUTES * 60000).toISOString().slice(0, 10); }
function isTime_(s) { return /^([01]\d|2[0-3]):[0-5]\d$/.test(s); }
function minutesOf_(t) { return Number(t.slice(0, 2)) * 60 + Number(t.slice(3, 5)); }
function timeText_(v) {
  if (v instanceof Date) return ('0' + v.getHours()).slice(-2) + ':' + ('0' + v.getMinutes()).slice(-2);
  return String(v === undefined || v === null ? '' : v);
}
function serviceDay_(r) { return isoDay_(r.service_date) || isoDay_(r.requested_date); }

function serviceListValues_(name, includeOff) {
  // Base stations and drones have their own tabs now (Org.gs); the old Lists values were carried over once.
  if (name === 'base_station' || name === 'drone') {
    if (!orgSeeded_()) ensureOrg_();
    return (name === 'base_station' ? stationRows_(includeOff) : droneRows_(includeOff)).map(r => String(r.name));
  }
  return readAll_('Lists').filter(l => l.list_name === name && (includeOff || l.active === 'Yes')).map(l => String(l.value));
}

// People a record can be credited to: the signed-in person, plus (for managers and admins) every active pilot.
function pilotChoices_(user) {
  const me = { email: String(user.email).toLowerCase(), name: user.name };
  if (user.role === 'Pilot') return [me];
  const out = [];
  readAll_('Users').forEach(u => {
    if (u.active !== 'Yes' || hiddenRow_(u)) return;
    const email = String(u.email).toLowerCase();
    if (u.role === 'Pilot' || email === me.email) out.push({ email: email, name: u.name });
  });
  if (!out.some(p => p.email === me.email)) out.push(me);
  return out.sort((a, b) => String(a.name).localeCompare(String(b.name)));
}

// ---------- reading rows ----------

function serviceCol_(name) { return SCHEMA.Services.indexOf(name) + 1; }

// Sheet row numbers of one farmer's service rows (reads a single column, so it stays fast with many rows).
function serviceRowNumbersForFarmer_(farmerId) {
  const sh = sheet_('Services');
  const last = sh.getLastRow();
  if (last < 2) return [];
  const rows = [];
  sh.getRange(2, serviceCol_('farmer_id'), last - 1, 1).getValues().forEach((r, i) => { if (String(r[0]) === farmerId) rows.push(i + 2); });
  return rows;
}

function findServiceRow_(serviceId) {
  const sh = sheet_('Services');
  const last = sh.getLastRow();
  if (last < 2 || !serviceId) return null;
  const ids = sh.getRange(2, 1, last - 1, 1).getValues();
  for (let i = 0; i < ids.length; i++) if (String(ids[i][0]) === serviceId) return readRowsAt_('Services', [i + 2])[0];
  return findArchivedService_(serviceId);   // an old job that moved to the archive (a read-only view with _archived)
}

// The last n rows of the tab (new records are always added at the end).
function readServicesTail_(n) {
  const last = sheet_('Services').getLastRow();
  if (last < 2) return [];
  const from = Math.max(2, last - n + 1);
  const rows = [];
  for (let r = from; r <= last; r++) rows.push(r);
  return readRowsAt_('Services', rows);
}

function farmerCard_(farmerId) {
  const e = indexEntry_(farmerId);
  if (!e) return null;
  const f = entryFarmer_(e);
  const crops = [];
  e.f.forEach(x => { if (crops.indexOf(x[1]) === -1) crops.push(x[1]); });
  return { farmer_id: e.id, full_name: f.full_name, phone_primary: f.phone_primary, village: f.village, ds_division: f.ds_division, district: f.district,
    status: f.status, do_not_contact: f.do_not_contact, marketing_consent: f.marketing_consent, total_acres: entryAcres_(e), crops: crops,
    latitude: f.latitude, longitude: f.longitude, gps_source: f.gps_source };
}

// A record as the browser gets it: no helper keys, the developer's email hidden, and money hidden from other pilots' records.
function serviceOut_(r, user) {
  const o = stripRow_(r);
  delete o._archived;
  o.requested_date = isoDay_(o.requested_date);
  o.service_date = isoDay_(o.service_date);
  o.start_time = timeText_(o.start_time);
  o.end_time = timeText_(o.end_time);
  if (user && !moneyAllowed_(user, r)) SERVICE_MONEY_COLS_.forEach(k => { o[k] = ''; });      // money only for people with the payment power (and, with the 'own' scope, only on their own jobs)
  return o;
}

function sortServices_(rows) {
  return rows.sort((a, b) => serviceDay_(b).localeCompare(serviceDay_(a)) || String(b.start_time).localeCompare(String(a.start_time)) || String(b.service_id).localeCompare(String(a.service_id)));
}

function isMine_(user, r) { return String(r.pilot_email).toLowerCase() === String(user.email).toLowerCase(); }

// What the record's "history" numbers say: only completed jobs count towards how much a farmer bought.
function summarizeServices_(rows, hideMoney) {
  const done = rows.filter(r => r.status === 'Completed');
  let acres = 0, minutes = 0, amount = 0, rated = 0, ratingSum = 0;
  const byType = {};
  done.forEach(r => {
    acres += Number(r.acres_covered) || 0;
    minutes += Number(r.duration_min) || 0;
    amount += Number(r.amount_charged) || 0;
    if (Number(r.satisfaction)) { rated++; ratingSum += Number(r.satisfaction); }
    const t = r.service_type || 'Not recorded';
    byType[t] = (byType[t] || 0) + 1;
  });
  const days = done.map(r => isoDay_(r.service_date)).filter(Boolean).sort();
  return {
    completed: done.length, acres: round2_(acres), hours: round2_(minutes / 60), amount: hideMoney ? null : Math.round(amount),
    avg_satisfaction: rated ? round2_(ratingSum / rated) : null, rated: rated, first: days[0] || '', last: days[days.length - 1] || '',
    open: rows.filter(r => r.status === 'Requested' || r.status === 'Scheduled').length, cancelled: rows.filter(r => r.status === 'Cancelled').length,
    by_type: Object.keys(byType).map(k => ({ name: k, services: byType[k] })).sort((a, b) => b.services - a.services)
  };
}

// ---------- screens: options, farmer history, lists ----------

function getServiceOptions() {
  const user = requireServiceUser_();
  return plain_({
    statuses: SERVICE_STATUSES, payment_statuses: PAYMENT_STATUSES,
    service_types: serviceListValues_('service_type'), drones: serviceListValues_('drone'), crops: listsMap_().crop,
    pilots: pilotChoices_(user), me: { email: String(user.email).toLowerCase(), name: user.name, role: user.role },
    today: localToday_(), edit_days: PILOT_EDIT_DAYS
  });
}

// Farmer search for the service screens: no NIC numbers, so a pilot only sees what is needed to find and contact the right person.
function findFarmersForService(query) {
  requireServiceUser_();
  return plain_(searchEntries_(query, 30, e => e.v[14] === 'Active').map(e => {
    const v = e.v;
    return { farmer_id: e.id, full_name: v[1], phone_primary: v[7], village: v[11], ds_division: v[10], district: v[9], status: v[14], total_acres: entryAcres_(e) };
  }));
}

// One farmer's service log with the totals: the "how much has this customer bought" view.
function getFarmerServices(farmerId) {
  const user = requireServiceUser_();
  const card = farmerCard_(String(farmerId || ''));
  if (!card) throw new Error('Farmer not found.');
  const all = farmerServiceRows_(card.farmer_id);
  const hideMoney = user.role === 'Pilot';
  const rows = sortServices_(all.map(r => serviceOut_(r, user)));
  return plain_({ farmer: card, summary: summarizeServices_(all.map(r => serviceOut_(r, user)), hideMoney), rows: rows.slice(0, 200), total: rows.length });
}

function getService(serviceId) {
  const user = requireServiceUser_();
  const rec = findServiceRow_(String(serviceId || ''));
  if (!rec) throw new Error('Service record not found.');
  if (user.role === 'Pilot' && !isMine_(user, rec)) throw new Error('Not authorised for this record.');
  return plain_({ service: serviceOut_(rec, user), farmer: farmerCard_(rec.farmer_id), can_edit: canEditService_(user, rec) });
}

function canEditService_(user, rec) {
  if (user.role === 'Admin' || user.role === 'Manager') return true;
  if (user.role !== 'Pilot' || !isMine_(user, rec)) return false;
  const made = new Date(rec.created_at).getTime();
  return isFinite(made) && Date.now() - made <= PILOT_EDIT_DAYS * 86400000;
}

function addFarmerNames_(rows) {
  const byId = indexLoad_().byId;
  rows.forEach(r => {
    const e = byId[r.farmer_id];
    r.farmer_name = e ? e.v[1] : r.farmer_id;
    r.farmer_place = e ? [e.v[11], e.v[10]].filter(Boolean).join(', ') : '';
  });
  return rows;
}

// The latest records for the entry screen: a pilot's own, or everyone's for managers and admins.
function listRecentServices() {
  const user = requireServiceUser_();
  let rows;
  if (user.role === 'Pilot') {
    // a pilot's own latest jobs, wherever they lie: the other pilots' records in the last rows of the tab must not push them out of sight
    const sh = sheet_('Services');
    const last = sh.getLastRow();
    const mine = [];
    if (last >= 2) sh.getRange(2, serviceCol_('pilot_email'), last - 1, 1).getValues().forEach((r, i) => { if (String(r[0]).toLowerCase() === String(user.email).toLowerCase()) mine.push(i + 2); });
    rows = readRowsAt_('Services', mine.slice(-RECENT_SERVICE_READ));
  } else rows = readServicesTail_(RECENT_SERVICE_READ);
  const out = sortServices_(rows.map(r => Object.assign(serviceOut_(r, user), { can_edit: canEditService_(user, r) })).slice()).slice(0, 15);
  return plain_(addFarmerNames_(out));
}

function cleanServiceFilter_(input, user) {
  const f = input || {};
  const out = { from: cleanDate_(f.from, 'From'), to: cleanDate_(f.to, 'To'), pilot: '', type: clean_(f.service_type).slice(0, 60), status: clean_(f.status), crop: clean_(f.crop).slice(0, 60), farmer_id: clean_(f.farmer_id).slice(0, 20) };
  if (out.from && out.to && out.from > out.to) throw new Error('"From" is after "To".');
  if (out.status && SERVICE_STATUSES.indexOf(out.status) === -1) throw new Error('Unknown status.');
  out.pilot = user.role === 'Pilot' ? String(user.email).toLowerCase() : String(f.pilot_email || '').trim().toLowerCase();
  return out;
}

function serviceMatches_(r, f) {
  const day = serviceDay_(r);
  if (f.from && (!day || day < f.from)) return false;
  if (f.to && (!day || day > f.to)) return false;
  if (f.pilot && String(r.pilot_email).toLowerCase() !== f.pilot) return false;
  if (f.type && String(r.service_type) !== f.type) return false;
  if (f.status && String(r.status) !== f.status) return false;
  if (f.crop && String(r.crop) !== f.crop) return false;
  if (f.farmer_id && String(r.farmer_id) !== f.farmer_id) return false;
  return true;
}

// The service log screen: all records that match the filters (a pilot only ever gets their own), newest first.
function listServices(filterInput) {
  const user = requireServiceUser_();
  const f = cleanServiceFilter_(filterInput, user);
  // Two steps, so the whole tab is not read in full: the columns the filters, the totals and the sort order need for every record, then the
  // complete rows of only the ones that are shown.
  const liveAll = readColumns_('Services', SERVICE_LIST_COLS_);
  const matched = liveAll.filter(r => serviceMatches_(r, f));
  const hideMoney = user.role === 'Pilot';
  const light = matched.map(r => { const o = serviceOut_(r, user); o._row = r._row; return o; });
  // old jobs that moved to the archive: only the months the dates touch are read (none at all while nothing is archived)
  const archived = {};
  withoutLiveIds_(archivedServiceRows_(f.from, f.to).filter(r => serviceMatches_(r, f)), liveAll).forEach(r => {
    const o = serviceOut_(r, user); o._row = 0; archived[String(r.service_id)] = r; light.push(o);
  });
  const top = sortServices_(light.slice()).slice(0, SERVICE_LIST_LIMIT);
  const full = {}; readRowsSpan_('Services', top.filter(o => o._row).map(o => o._row)).forEach(r => { full[r._row] = r; });
  const shown = top.map(o => { const r = o._row ? full[o._row] : archived[String(o.service_id)]; return Object.assign(serviceOut_(r, user), { can_edit: canEditService_(user, r) }); });
  return plain_({ rows: addFarmerNames_(shown), total: light.length, truncated: light.length > SERVICE_LIST_LIMIT,
    summary: summarizeServices_(light, hideMoney) });
}

// ---------- saving ----------

// Checks one submitted record and returns the cleaned columns to store, or throws a message in plain words.
function validateService_(input, user, existing) {
  const keep = existing || {};
  const status = String(input.status || keep.status || 'Completed');
  if (SERVICE_STATUSES.indexOf(status) === -1) throw new Error('Choose a status.');
  if (status === 'Cancelled' && !existing) throw new Error('Only an existing record can be cancelled.');
  const today = localToday_();
  let requested = cleanDate_(input.requested_date, 'Requested date');
  const serviceDate = cleanDate_(input.service_date, 'Service date');
  if (status === 'Requested' && !requested) requested = today;
  if (requested && requested > today) throw new Error('The requested date cannot be in the future.');
  if (status === 'Completed') {
    if (!serviceDate) throw new Error('Service date is required.');
    if (serviceDate > today) throw new Error('A completed service cannot be dated in the future.');
  }
  if (status === 'Scheduled' && !serviceDate) throw new Error('Choose the day the service is planned for.');
  if (requested && serviceDate && requested > serviceDate && status !== 'Requested') throw new Error('The service cannot be dated before the day it was requested.');

  const start = String(input.start_time || '').trim();
  const end = String(input.end_time || '').trim();
  if (start && !isTime_(start)) throw new Error('Start time is not a valid time.');
  if (end && !isTime_(end)) throw new Error('End time is not a valid time.');
  if ((start && !end) || (end && !start)) throw new Error('Enter both the start time and the end time.');
  if (start && end && minutesOf_(end) <= minutesOf_(start)) throw new Error('The end time must be after the start time.');
  if (status === 'Completed' && user.role === 'Pilot' && !start) throw new Error('Start time and end time are required.');

  // who flew it
  let pilotEmail = String(keep.pilot_email || '');
  let pilotName = String(keep.pilot_name || '');
  if (user.role === 'Pilot') {
    pilotEmail = String(user.email).toLowerCase(); pilotName = user.name;
  } else {
    const chosen = String(input.pilot_email || '').trim().toLowerCase();
    if (chosen && !(existing && chosen === 'system')) {
      const row = findUserByEmail_(chosen);
      if (!row || row.active !== 'Yes' || hiddenRow_(row) || row.role === 'DataEntry') throw new Error('Choose the pilot from the list.');
      pilotEmail = String(row.email).toLowerCase(); pilotName = row.name;
    } else if (!existing && !pilotEmail) {
      if (status === 'Completed') throw new Error('Choose the pilot who did the job.');
    }
  }

  const type = checkList_(clean_(input.service_type), serviceListValues_('service_type'), 'Service type', keep.service_type);
  if ((status === 'Completed' || status === 'Scheduled') && !type) throw new Error('Choose the kind of service.');
  const crop = checkList_(clean_(input.crop), listsMap_().crop, 'Crop', keep.crop);
  if (status === 'Completed' && !crop) throw new Error('Choose the crop.');
  const drones = serviceListValues_('drone');
  const drone = drones.length ? checkList_(clean_(input.drone), drones, 'Drone', keep.drone) : '';
  const acres = cleanNumber_(input.acres_covered, 'Acres covered', 0, MAX_SERVICE_ACRES);
  if (status === 'Completed' && (acres === '' || acres <= 0)) throw new Error('Acres covered must be more than 0.');
  const payment = clean_(input.payment_status);
  if (payment && PAYMENT_STATUSES.indexOf(payment) === -1) throw new Error('Choose a payment status from the list.');
  let satisfaction = '';
  if (input.satisfaction !== '' && input.satisfaction !== null && input.satisfaction !== undefined) {
    satisfaction = Number(input.satisfaction);
    if (!Number.isInteger(satisfaction) || satisfaction < 1 || satisfaction > 5) throw new Error('Satisfaction is a score from 1 to 5.');
    if (status !== 'Completed') {
      if (!existing) throw new Error('Satisfaction can be recorded once the service is completed.');
      satisfaction = '';   // a record changed to cancelled (or back to a booking) no longer carries a score
    }
  }
  const amount = cleanNumber_(input.amount_charged, 'Amount charged', 0, 100000000);
  return {
    status: status, requested_date: requested, service_date: serviceDate, start_time: start, end_time: end,
    duration_min: start && end ? minutesOf_(end) - minutesOf_(start) : '',
    pilot_name: pilotName, pilot_email: pilotEmail, drone: drone, service_type: type, crop: crop,
    acres_covered: acres === '' ? '' : round2_(acres), product_used: clean_(input.product_used).slice(0, 80),
    quantity_l: cleanNumber_(input.quantity_l, 'Quantity', 0, 100000), amount_charged: amount === '' ? '' : round2_(amount),
    payment_status: payment, satisfaction: satisfaction, feedback: clean_(input.feedback).slice(0, 300), notes: clean_(input.notes).slice(0, 300)
  };
}

// A stored record in the shape of a form submission, so an edit that mentions only some fields keeps the rest.
function inputFromRecord_(r) {
  const o = {};
  SCHEMA.Services.forEach(h => { o[h] = r[h]; });
  o.requested_date = isoDay_(r.requested_date); o.service_date = isoDay_(r.service_date);
  o.start_time = timeText_(r.start_time); o.end_time = timeText_(r.end_time);
  return o;
}

function saveService(input) {
  const user = requireServiceUser_();
  return withLock_(() => saveServiceLocked_(user, input || {}));
}

function saveServiceLocked_(user, input) {
  let existing = null;
  if (input.service_id) {
    existing = findServiceRow_(String(input.service_id));
    if (!existing) throw new Error('Service record not found.');
    if (!canEditService_(user, existing)) throw new Error('Not authorised: a pilot can only change their own records from the last ' + PILOT_EDIT_DAYS + ' days.');
    // Whatever the change does not mention stays as it was (cancelling a job, or adding the satisfaction score later).
    input = Object.assign(inputFromRecord_(existing), input);
  }
  const farmerId = existing ? existing.farmer_id : String(input.farmer_id || '').trim();
  if (!farmerId || !indexEntry_(farmerId)) throw new Error('Choose the farmer first.');
  const core = validateService_(input, user, existing);

  if (existing) {
    if (existing._archived) existing = restoreServiceRow_(existing.service_id);   // an old job is brought back to the live sheet to be corrected
    const obj = Object.assign({}, existing, core, auditCols_(false));
    writeRowObject_('Services', existing._row, obj);
    audit_('update', 'Services', obj.service_id, farmerId + ' ' + core.status, { farmer_id: farmerId });
    return { service_id: obj.service_id, created: false };
  }
  // The same job saved twice in a row (a double tap on a slow connection) is refused.
  const me = String(user.email).toLowerCase();
  const twin = readServicesTail_(60).some(r => String(r.farmer_id) === farmerId && String(r.status) === core.status && isoDay_(r.service_date) === core.service_date &&
    String(r.service_type) === core.service_type && timeText_(r.start_time) === core.start_time && timeText_(r.end_time) === core.end_time &&
    Number(r.acres_covered) === Number(core.acres_covered) && String(r.created_by).toLowerCase() === me && Date.now() - new Date(r.created_at).getTime() < 600000);
  if (twin) throw new Error('This service was already saved a moment ago.');
  const id = nextId_('SV', 6);
  const obj = Object.assign({ service_id: id, farmer_id: farmerId }, core, auditCols_(true));
  appendObjects_('Services', [obj]);
  audit_('create', 'Services', id, farmerId + ' ' + core.status + ' ' + (core.acres_covered === '' ? '' : core.acres_covered + ' ac'), { farmer_id: farmerId });
  return { service_id: id, created: true };
}

// ---------- Admin: the lists behind the service form ----------

function getServiceSetup() {
  requireRole_(['Admin']);
  const rows = readAll_('Lists');
  return plain_({ lists: SERVICE_LISTS.map(l => ({ name: l[0], label: l[1], values: rows.filter(r => r.list_name === l[0]).map(r => ({ value: String(r.value), active: r.active === 'Yes' })) })) });
}

function serviceListName_(name) {
  if (!SERVICE_LISTS.some(l => l[0] === name)) throw new Error('Unknown list.');
  return name;
}

// The sheet row of a value in the Lists tab, or 0.
function listRowOf_(listName, value) {
  const sh = sheet_('Lists');
  const last = sh.getLastRow();
  if (last < 2) return 0;
  const vals = sh.getRange(2, 1, last - 1, 2).getValues();
  for (let i = 0; i < vals.length; i++) if (vals[i][0] === listName && String(vals[i][1]).toLowerCase() === String(value).toLowerCase()) return i + 2;
  return 0;
}

function addServiceListValue(listName, value) {
  requireRole_(['Admin']);
  const name = serviceListName_(listName);
  const v = clean_(value).slice(0, 60);
  if (!v) throw new Error('Type the new value first.');
  withLock_(() => {
    const row = listRowOf_(name, v);
    if (row) {
      if (sheet_('Lists').getRange(row, 3).getValue() === 'Yes') throw new Error('"' + v + '" is already in the list.');
      touch_('Lists');
      sheet_('Lists').getRange(row, 3).setValue('Yes');
    } else {
      appendObjects_('Lists', [{ list_name: name, value: v, active: 'Yes' }]);
    }
    audit_('update', 'Lists', name, 'added ' + v);
  });
  return true;
}

function setServiceListValueActive(listName, value, active) {
  requireRole_(['Admin']);
  const name = serviceListName_(listName);
  withLock_(() => {
    const row = listRowOf_(name, clean_(value));
    if (!row) throw new Error('That value is not in the list.');
    touch_('Lists');
    sheet_('Lists').getRange(row, 3).setValue(active ? 'Yes' : 'No');
    audit_('update', 'Lists', name, (active ? 'switched on ' : 'switched off ') + value);
  });
  return true;
}

// ---- Setup.gs
// Builds the database tabs and loads starter data. Safe to run again: it only adds what is missing
// and never overwrites existing rows.

function setupDatabase() {
  requireRole_(['Admin']);
  resetDbMemo_();
  const ss = db_();
  PropertiesService.getScriptProperties().setProperty('SPREADSHEET_ID', ss.getId());

  const report = [];
  Object.keys(SCHEMA).forEach(name => report.push(ensureSheet_(ss, name)));

  seedConfig_();
  seedOwnerAdmin_();
  seedLists_();
  seedServiceLists_();
  seedStarterQuestions_();

  const defaultSheet = ss.getSheetByName('Sheet1');
  if (defaultSheet && ss.getSheets().length > 1 && defaultSheet.getLastRow() <= 1) ss.deleteSheet(defaultSheet);

  Logger.log(report.join('\n'));
  return report;
}

function ensureSheet_(ss, name) {
  const headers = SCHEMA[name];
  let sh = ss.getSheetByName(name);
  let status = 'ok';
  if (!sh) {
    sh = ss.insertSheet(name);
    status = 'created';
  }
  // A table that gained columns needs room for them first.
  if (sh.getMaxColumns() < headers.length) sh.insertColumnsAfter(sh.getMaxColumns(), headers.length - sh.getMaxColumns());
  const existing = sh.getRange(1, 1, 1, headers.length).getValues()[0];
  // FarmerIndex is derived data (see FarmerIndex.gs): if its layout changed it is simply emptied and rebuilt on first use.
  if (name === 'FarmerIndex' && !existing.every(c => c === '') && existing.join('|') !== headers.join('|')) { sh.clear(); status = 'reset'; existing.fill(''); }
  const blank = existing.every(c => c === '');
  const filled = existing.slice();
  while (filled.length && filled[filled.length - 1] === '') filled.pop();
  const isOlderVersion = filled.length > 0 && filled.length < headers.length && filled.every((c, i) => c === headers[i]);
  if (blank) {
    sh.getRange(1, 1, 1, headers.length).setValues([headers]);
    sh.setFrozenRows(1);
    sh.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#e8f0e8');
  } else if (isOlderVersion) {
    // The tab has the first columns of the current design: add the new ones to the right, data stays where it is.
    sh.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold').setBackground('#e8f0e8');
    status = 'columns added';
  } else if (existing.join('|') !== headers.join('|')) {
    if (sh.getLastRow() <= 1) {
      // No data yet, so the headers can be rewritten safely.
      sh.getRange(1, 1, 1, Math.max(headers.length, sh.getLastColumn())).clearContent();
      sh.getRange(1, 1, 1, headers.length).setValues([headers]).setFontWeight('bold').setBackground('#e8f0e8');
      status = 'headers updated';
    } else {
      status = 'HEADER MISMATCH (has data, left untouched, fix by hand)';
    }
  }
  // A new tab has 26 columns. Every cell in the grid counts toward Google's 10 million cell limit, used or not,
  // so the columns after the last header are removed.
  const extraColumns = sh.getMaxColumns() - headers.length;
  if (extraColumns > 0 && status.indexOf('MISMATCH') === -1) sh.deleteColumns(headers.length + 1, extraColumns);
  headers.forEach((h, i) => {
    if (isTextColumn_(h)) sh.getRange(2, i + 1, Math.max(sh.getMaxRows() - 1, 1), 1).setNumberFormat('@');
  });
  return name + ': ' + status;
}

